<?php session_start(); if(!isset($_SESSION['courier_id'])){header('Location: login.php');exit;} require_once __DIR__.'/../fastfood/database.php'; $cid=(int)$_SESSION['courier_id']; if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)$_POST['order_id'];$st=$_POST['status'];$allowed=['picked_up','on_the_way','delivered','cancelled'];if(in_array($st,$allowed,true)){$orderStatus=$st==='delivered'?'yakunlangan':($st==='cancelled'?'bekor qilingan':'yetkazilmoqda');$pdo->prepare('UPDATE orders SET delivery_status=?,status=? WHERE id=? AND courier_id=?')->execute([$st,$orderStatus,$id,$cid]);} header('Location: dashboard.php');exit;} $me=$pdo->prepare('SELECT * FROM delivery_couriers WHERE id=?');$me->execute([$cid]);$courier=$me->fetch();$orders=$pdo->prepare("SELECT * FROM orders WHERE order_type='delivery' AND courier_id=? AND delivery_status NOT IN ('delivered','cancelled') ORDER BY created_at DESC");$orders->execute([$cid]);$orders=$orders->fetchAll(); ?>
