</head><body><main class="wrap"><div class="top"><div><div style="opacity:.7">KURYER</div><h1 style="margin:4px 0"><?=htmlspecialchars($courier['name'])?></h1><div><?=htmlspecialchars($courier['vehicle']??'')?></div></div><span class="lang-switch" id="langSwitch"><button onclick="setLanguage('uz')" data-lang="uz">UZ</button><button onclick="setLanguage('ru')" data-lang="ru">RU</button><button onclick="setLanguage('en')" data-lang="en">EN</button></span><a style="color:#fff" href="logout.php">Chiqish</a></div><?php foreach($orders as $o): ?><article class="job"><h2>#<?=$o['id']?> — <?=htmlspecialchars($o['customer_name'])?></h2><div class="meta">📞 <?=htmlspecialchars($o['phone'])?><br>📍 <?=htmlspecialchars($o['address'])?><br>💰 <?=number_format($o['total'],0,'',' ')?> so‘m</div><?php if($o['delivery_lat']&&$o['delivery_lng']): ?><a class="map" target="_blank" href="https://www.openstreetmap.org/?mlat=<?=$o['delivery_lat']?>&mlon=<?=$o['delivery_lng']?>#map=18/<?=$o['delivery_lat']?>/<?=$o['delivery_lng']?>">🗺️ Xarita / GPS</a><?php endif; ?><div class="actions"><form method="post"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="status" value="picked_up"><button class="btn secondary">📦 Buyurtmani oldim</button></form><form method="post"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="status" value="on_the_way"><button class="btn primary">🛵 Yo‘ldaman</button></form><form method="post"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="status" value="delivered"><button class="btn primary">✅ Yetkazdim</button></form></div></article><?php endforeach; if(!$orders): ?><div class="job" style="text-align:center;padding:50px">🎉 Hozir sizga biriktirilgan buyurtma yo‘q.</div><?php endif; ?></main><script src="../js/global-i18n.js"></script><script src="../js/lang-switch.js"></script><script src="../js/global-i18n.js"></script><script src="../js/lang-switch.js"></script>